                    <div className="flex gap-4">
                      <div className="flex-1"><label className="text-[10px] font-bold text-slate-400 uppercase">{t('weight')}</label><input type="range" min="1" max="5" value={conn.width} onChange={e => { const updated = [...localSettings.connectionTypes]; updated[idx].width = parseInt(e.target.value); setLocalSettings({ ...localSettings, connectionTypes: updated }); }} className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer" /></div>
                      <div className="flex-1"><label className="text-[10px] font-bold text-slate-400 uppercase">{t('style')}</label><select value={conn.dashStyle} onChange={e => { const updated = [...localSettings.connectionTypes]; updated[idx].dashStyle = e.target.value as any; setLocalSettings({ ...localSettings, connectionTypes: updated }); }} className="w-full text-xs p-1 border border-slate-200 rounded"><option value="solid">Solid</option><option value="dashed">Dashed</option><option value="dotted">Dotted</option></select></div>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {activeTab === 'tags' && (
              <div className="space-y-4">
                <div className="flex items-center justify-between mb-2">
                  <h3 className="text-sm font-bold text-slate-800 uppercase tracking-widest text-[10px]">{t('tag_styles')}</h3>
                  <button onClick={addTag} className="text-xs font-bold text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1">
                    <Plus size={14} /> {t('add_field')}
                  </button>
                </div>
                {(localSettings.tags || []).map((tag, idx) => (
                  <div key={tag.id} className="flex items-center gap-3 p-3 bg-white border border-slate-200 rounded-xl group">
                    <input type="color" value={tag.color} onChange={e => { const updated = [...(localSettings.tags || [])]; updated[idx].color = e.target.value; setLocalSettings({ ...localSettings, tags: updated }); }} className="w-8 h-8 rounded-lg cursor-pointer border-0 bg-transparent" />
                    <input type="text" value={tag.name} onChange={e => { const updated = [...(localSettings.tags || [])]; updated[idx].name = e.target.value; setLocalSettings({ ...localSettings, tags: updated }); }} className="flex-1 bg-transparent text-sm font-medium focus:ring-0 border-0 p-0" />
                    <button onClick={() => setLocalSettings(p => ({ ...p, tags: (p.tags || []).filter(t => t.id !== tag.id)}))} className="opacity-0 group-hover:opacity-100 p-1.5 text-slate-400 hover:text-red-500 transition-all"><Trash2 size={16} /></button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-6 py-2 text-slate-600 text-sm font-semibold">{t('cancel')}</button>
          <button onClick={() => { onSave(localSettings); onClose(); }} className="px-8 py-2 bg-slate-900 text-white rounded-xl text-sm font-bold shadow-lg shadow-slate-200">{t('apply_config')}</button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { X, Plus, Trash2, Tag as TagIcon, Database, MessageSquare, Key } from 'lucide-react';
import { Node } from 'reactflow';
import { NodeData, NodeCardType, TableColumn, GlobalSettings, Tag } from '../types.ts';
import { translations } from '../translations.ts';

interface EditorModalProps {
  node: Node<NodeData>;
  settings: GlobalSettings;
  onClose: () => void;
  onSave: (data: Partial<NodeData>) => void;
  language: 'en' | 'zh';
}

export const EditorModal: React.FC<EditorModalProps> = ({ node, settings, onClose, onSave, language }) => {
  const [label, setLabel] = useState(node.data.label);
  const [cardType, setCardType] = useState<NodeCardType>(node.data.cardType);

  const initialCatId = node.data.categoryId || (
    cardType === NodeCardType.TABLE 
      ? (settings.tableCategories.find(c => c.isDefault) || settings.tableCategories[0]).id
      : (settings.logicCategories.find(c => c.isDefault) || settings.logicCategories[0]).id
  );

  const [categoryId, setCategoryId] = useState(initialCatId);
  const [columns, setColumns] = useState<TableColumn[]>(node.data.columns || []);
  const [description, setDescription] = useState(node.data.description || '');
  const [bulletPoints, setBulletPoints] = useState<string[]>(node.data.bulletPoints || []);
  const [comment, setComment] = useState(node.data.comment || '');
  const [dataSourceId, setDataSourceId] = useState(node.data.dataSourceId || '');
  const [assignedTags, setAssignedTags] = useState<string[]>(node.data.tags || []);

  const isTable = cardType === NodeCardType.TABLE;
  const isLogic = cardType === NodeCardType.LOGIC_NOTE;

  const t = (key: keyof typeof translations.en) => translations[language][key] || key;

  const toggleTag = (tagId: string) => {
    setAssignedTags(prev => 
      prev.includes(tagId) ? prev.filter(id => id !== tagId) : [...prev, tagId]
    );
  };

  return (
    <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-2xl rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        <div className="px-6 py-4 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
          <h2 className="text-lg font-bold text-slate-800 tracking-tight">{t('node_properties')}</h2>
          <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-400"><X size={20} /></button>
        </div>

        <div className="p-6 overflow-y-auto flex-1 space-y-6 custom-scrollbar">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2 sm:col-span-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5">{t('component_identity')}</label>
              <input type="text" value={label} onChange={e => setLabel(e.target.value)} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:ring-2 focus:ring-blue-500 outline-none" />
            </div>
            <div className="col-span-2 sm:col-span-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5">{t('category')}</label>
              <select value={categoryId} onChange={e => setCategoryId(e.target.value)} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:ring-2 focus:ring-blue-500 outline-none">
                {isTable ? (
                  settings.tableCategories.map(cat => (
                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                  ))
                ) : (
                  settings.logicCategories.map(cat => (
                    <option key={cat.id} value={cat.id}>{cat.name}</option>
                  ))
                )}
              </select>
            </div>
          </div>

          {/* Tags Assignment */}
          <div className="pt-4 border-t border-slate-100">
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2.5 flex items-center gap-1.5">
              <TagIcon size={10} /> {t('assign_tags')}
            </label>
            <div className="flex flex-wrap gap-2">
              {(settings.tags || []).map(tag => (
                <button
                  key={tag.id}
                  onClick={() => toggleTag(tag.id)}
                  className={`px-3 py-1.5 rounded-full text-xs font-bold transition-all border flex items-center gap-2 ${
                    assignedTags.includes(tag.id) 
                      ? 'bg-slate-900 text-white border-slate-900 shadow-md scale-105' 
                      : 'bg-white text-slate-500 border-slate-200 hover:border-slate-400'
                  }`}
                >
                  <div className="w-2 h-2 rounded-full" style={{ backgroundColor: tag.color }} />
                  {tag.name}
                </button>
              ))}
              {(settings.tags || []).length === 0 && (
                <span className="text-xs italic text-slate-400">{t('none')}</span>
              )}
            </div>
          </div>

          {isTable && (
            <div className="grid grid-cols-2 gap-4 pt-4 border-t border-slate-100">
               <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5"><Database size={10} /> {t('data_source')}</label>
                <select value={dataSourceId} onChange={e => setDataSourceId(e.target.value)} className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold focus:ring-2 focus:ring-blue-500 outline-none">
                  <option value="">{t('select_source')}</option>
                  {settings.dataSources.map(src => (
                    <option key={src.id} value={src.id}>{src.name}</option>
                  ))}
                </select>
              </div>
              <div className="col-span-2">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 flex items-center gap-1.5"><MessageSquare size={10} /> {t('comment')}</label>
                <textarea value={comment} onChange={e => setComment(e.target.value)} rows={2} placeholder={t('comment')} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>
            </div>
          )}

          <div className="pt-6 border-t border-slate-100">
            {isTable ? (
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-sm font-bold text-slate-700">{t('fields_schema')}</span>
                  <button onClick={() => setColumns([...columns, { id: Date.now().toString(), name: 'New Field', isKey: false }])} className="text-xs font-bold text-blue-600 flex items-center gap-1">
                    <Plus size={14} /> {t('add_field')}
                  </button>
                </div>
                <div className="space-y-3">
                  {columns.map(col => (
                    <div key={col.id} className="flex flex-wrap items-center gap-2 p-3 bg-slate-50/50 border border-slate-100 rounded-xl group transition-all hover:bg-white hover:shadow-sm">
                      <div className="flex-1 min-w-[150px]">
                        <input type="text" value={col.name} onChange={e => setColumns(columns.map(c => c.id === col.id ? { ...c, name: e.target.value } : c))} className="w-full px-3 py-1.5 bg-white border border-slate-200 rounded-lg text-xs font-bold uppercase tracking-tight focus:ring-2 focus:ring-blue-500 outline-none" />
                      </div>
                      <div className="w-32">
                        <select value={col.typeId || ''} onChange={e => setColumns(columns.map(c => c.id === col.id ? { ...c, typeId: e.target.value || undefined } : c))} className="w-full px-2 py-1.5 bg-white border border-slate-200 rounded-lg text-[10px] font-bold uppercase outline-none focus:ring-2 focus:ring-blue-500">
                          <option value="">{t('none')}</option>
                          {settings.fieldTypes.map(ft => (
                            <option key={ft.id} value={ft.id}>{ft.name}</option>
                          ))}
                        </select>
                      </div>
                      <div className="flex items-center gap-1.5 px-3 py-1 bg-white border border-slate-200 rounded-lg">
                        <input type="checkbox" id={`key-${col.id}`} checked={col.isKey} onChange={e => setColumns(columns.map(c => c.id === col.id ? { ...c, isKey: e.target.checked } : c))} className="w-3 h-3 text-blue-600 rounded focus:ring-blue-500" />
                        <label htmlFor={`key-${col.id}`} className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-1 cursor-pointer select-none">
                          <Key size={10} className={col.isKey ? 'text-amber-500' : 'text-slate-300'} />
                          {t('key_field')}
                        </label>
                      </div>
                      <button onClick={() => setColumns(columns.filter(c => c.id !== col.id))} className="p-2 text-slate-300 hover:text-red-500 transition-colors"><Trash2 size={16} /></button>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                <div><label className="block text-sm font-bold text-slate-700 mb-2">{t('internal_logic')}</label><textarea value={description} onChange={e => setDescription(e.target.value)} rows={3} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-medium outline-none focus:ring-2 focus:ring-blue-500" /></div>
                <div className="flex items-center justify-between"><span className="text-sm font-bold text-slate-700">{t('directives')}</span><button onClick={() => setBulletPoints([...bulletPoints, 'New Point'])} className="text-xs font-bold text-purple-600 flex items-center gap-1"><Plus size={14} /> {t('add_point')}</button></div>
                {bulletPoints.map((p, idx) => (
                  <div key={idx} className="flex gap-2">
                    <input type="text" value={p} onChange={e => { const b = [...bulletPoints]; b[idx] = e.target.value; setBulletPoints(b); }} className="flex-1 px-3 py-1.5 bg-slate-50 border border-slate-200 rounded-lg text-xs" />
                    <button onClick={() => setBulletPoints(bulletPoints.filter((_, i) => i !== idx))} className="p-2 text-slate-300 hover:text-red-500"><Trash2 size={14} /></button>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-100 flex justify-end gap-3">
          <button onClick={onClose} className="px-6 py-2 text-slate-600 text-sm font-bold">{t('cancel')}</button>
          <button onClick={() => onSave({ label, categoryId, columns, description, bulletPoints, comment, dataSourceId, tags: assignedTags })} className="px-8 py-2 bg-slate-900 text-white rounded-xl text-sm font-bold shadow-lg">{t('commit_update')}</button>
        </div>
      </div>
    </div>
  );
};

import React, { memo } from 'react';
import { Handle, Position, NodeProps } from 'reactflow';
import { Trash2, Edit3, Database, FileText, BarChart2, MessageCircle, Key } from 'lucide-react';
import { NodeData, NodeCardType, GlobalSettings } from '../types.ts';

const HEADER_SIZES = { sm: 'text-[10px]', md: 'text-[12px]', lg: 'text-[14px]' };
const CONTENT_SIZES = { sm: 'text-[10px]', md: 'text-[11px]', lg: 'text-[13px]' };
const HIDE_ALL_VALUE = '__HIDE_ALL__';

export const BlueprintCard = memo(({ data, id, selected }: NodeProps<NodeData & { settings: GlobalSettings }>) => {
  const isTable = data.cardType === NodeCardType.TABLE;
  const isLogic = data.cardType === NodeCardType.LOGIC_NOTE;

  // Resolve dynamic category color
  let headerColor = '#ea580c'; 
  if (isTable) {
    const category = data.settings?.tableCategories.find(c => c.id === data.categoryId);
    headerColor = category ? category.color : '#2563eb';
  } else if (isLogic) {
    const category = data.settings?.logicCategories.find(c => c.id === data.categoryId);
    headerColor = category ? category.color : '#9333ea';
  }

  const appearance = data.appearance;
  const headerFontSizeClass = HEADER_SIZES[appearance?.headerFontSize || 'sm'];
  const contentFontSizeClass = CONTENT_SIZES[appearance?.contentFontSize || 'sm'];

  // Filtering Logic
  let isFilteredOut = false;

  // Category Filtering
  if (isTable && data.activeTableFilter) {
    if (data.activeTableFilter === HIDE_ALL_VALUE || data.categoryId !== data.activeTableFilter) {
      isFilteredOut = true;
    }
  }
  if (isLogic && data.activeLogicFilter) {
    if (data.activeLogicFilter === HIDE_ALL_VALUE || data.categoryId !== data.activeLogicFilter) {
      isFilteredOut = true;
    }
  }

  // Tag Filtering
  if (data.activeTagFilter) {
    if (data.activeTagFilter === HIDE_ALL_VALUE) {
      isFilteredOut = true;
    } else if (!data.tags?.includes(data.activeTagFilter)) {
      isFilteredOut = true;
    }
  }

  const cardOpacityClass = isFilteredOut ? 'opacity-10 grayscale pointer-events-none' : 'opacity-100';

  const theme = {
    border: selected ? 'border-slate-900 ring-2 ring-slate-100' : 'border-slate-100',
    icon: isTable ? <Database size={14} /> : (isLogic ? <FileText size={14} /> : <BarChart2 size={14} />),
    accent: headerColor
  };

  const dataSourceName = isTable && data.dataSourceId 
    ? data.settings?.dataSources.find(s => s.id === data.dataSourceId)?.name 
    : null;

  const handleClasses = `!w-4 !h-4 !bg-slate-400 !border-2 !border-white shadow-sm transition-all duration-200 hover:scale-125 hover:!bg-blue-500 z-50 ${selected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`;

  // Resolve Tag UI components
  const tagIndicators = (data.tags || []).map(tagId => {
    const tag = data.settings?.tags.find(t => t.id === tagId);
    return tag ? (
      <div 
        key={tag.id} 
        className="w-2.5 h-4 first:rounded-tl-lg last:rounded-tr-lg shadow-[0_1px_2px_rgba(0,0,0,0.1)]" 
        style={{ backgroundColor: tag.color }}
        title={tag.name}
      />
    ) : null;
  });

  return (
    <div className={`group min-w-[220px] max-w-[320px] rounded-xl overflow-hidden border shadow-sm transition-all duration-300 bg-white ${theme.border} ${cardOpacityClass}`}>
      {/* Visual Tag Bookmarks */}
      <div className="absolute top-0 left-4 flex gap-[1px] pointer-events-none z-10">
        {tagIndicators}
      </div>

      {/* Universal Handles */}
      <Handle type="target" position={Position.Top} id="t-t" className={handleClasses} />
      <Handle type="source" position={Position.Top} id="t-s" className={handleClasses} style={{ background: 'transparent', border: 'none' }} />
      <Handle type="target" position={Position.Bottom} id="b-t" className={handleClasses} />
      <Handle type="source" position={Position.Bottom} id="b-s" className={handleClasses} style={{ background: 'transparent', border: 'none' }} />
      <Handle type="target" position={Position.Left} id="l-t" className={handleClasses} />
      <Handle type="source" position={Position.Left} id="l-s" className={handleClasses} style={{ background: 'transparent', border: 'none' }} />
      <Handle type="target" position={Position.Right} id="r-t" className={handleClasses} />
      <Handle type="source" position={Position.Right} id="r-s" className={handleClasses} style={{ background: 'transparent', border: 'none' }} />

      <div style={{ backgroundColor: headerColor }} className="p-3 flex items-center justify-between text-white gap-3 transition-colors duration-300 relative">
        <div className="flex items-center gap-2 overflow-hidden">
          <div className="p-1.5 bg-white/20 rounded backdrop-blur-sm flex-shrink-0">{theme.icon}</div>
          <h3 className={`font-bold truncate uppercase tracking-widest ${headerFontSizeClass}`}>{data.label}</h3>
        </div>
        {!isFilteredOut && (
          <div className="flex items-center gap-1.5 ml-2">
            <button onClick={() => data.onEdit?.(id)} className="p-1 hover:bg-white/20 rounded transition-colors"><Edit3 size={12} /></button>
            <button onClick={() => data.onDelete?.(id)} className="p-1 hover:bg-white/20 rounded transition-colors"><Trash2 size={12} /></button>
          </div>
        )}
      </div>

      <div className="p-4 max-h-[400px] overflow-y-auto custom-scrollbar">
        {isTable && (
          <>
            {(dataSourceName || data.comment) && (
              <div className="mb-4 space-y-2 border-b border-slate-50 pb-3">
                {dataSourceName && (
                  <div className="flex items-center gap-2">
                    <Database size={12} className="text-slate-400" />
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{dataSourceName}</span>
                  </div>
                )}
                {data.comment && (
                  <div className="flex gap-2">
                    <MessageCircle size={12} className="text-slate-400 mt-0.5 shrink-0" />
                    <p className={`text-slate-500 italic ${contentFontSizeClass}`}>{data.comment}</p>
                  </div>
                )}
              </div>
            )}
            <div className="flex flex-col gap-1.5">
              {data.columns?.map(col => {
                const fType = data.settings?.fieldTypes.find(ft => ft.id === col.typeId);
                return (
                  <div key={col.id} className="flex items-center gap-2 py-1.5 px-2 hover:bg-slate-50 rounded-md transition-colors group/row">
                    <div className="flex-shrink-0 flex items-center justify-center">
                      {col.isKey ? (
                        <Key size={10} className="text-amber-500" />
                      ) : (
                        <div className="w-1 h-1 rounded-full" style={{ backgroundColor: headerColor }} />
                      )}
                    </div>
                    <span className={`text-slate-600 font-bold uppercase tracking-tight flex-1 truncate ${contentFontSizeClass} ${col.isKey ? 'text-slate-900' : ''}`}>
                      {col.name}
                    </span>
                    {fType && (
                      <span className="text-[8px] font-black bg-slate-100 text-slate-400 px-1.5 py-0.5 rounded-full uppercase tracking-tighter shrink-0">
                        {fType.name}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          </>
        )}

        {isLogic && (
          <div className="space-y-3">
            <p className={`text-slate-500 leading-relaxed font-medium ${contentFontSizeClass}`}>{data.description}</p>
            {data.bulletPoints?.map((p, idx) => (
              <div key={idx} className="flex gap-2 text-slate-600">
                <span style={{ color: headerColor }}>•</span>
                <span className={contentFontSizeClass}>{p}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
});

import React from 'react';
import { EdgeProps, getSmoothStepPath, EdgeLabelRenderer, BaseEdge } from 'reactflow';
import { Edit3, Trash2 } from 'lucide-react';
import { GlobalSettings } from '../types.ts';

const HIDE_ALL_VALUE = '__HIDE_ALL__';

export const BlueprintEdge = ({
  id, sourceX, sourceY, targetX, targetY, sourcePosition, targetPosition,
  style = {}, markerEnd, label, selected, data
}: EdgeProps) => {
  const [edgePath, labelX, labelY] = getSmoothStepPath({ sourceX, sourceY, sourcePosition, targetX, targetY, targetPosition });

  const settings: GlobalSettings = data.settings;
  const connType = settings?.connectionTypes.find(t => t.id === data.typeId);

  const finalStroke = connType?.color || '#94a3b8';
  const finalWidth = connType?.width || 2;
  const dashArray = connType?.dashStyle === 'dashed' ? '5,5' : connType?.dashStyle === 'dotted' ? '2,2' : undefined;

  // Filtering Logic for Edges
  let isFilteredOut = false;

  // 1. Check specific edge filter
  if (data.activeEdgeFilter) {
    if (data.activeEdgeFilter === HIDE_ALL_VALUE || data.typeId !== data.activeEdgeFilter) {
      isFilteredOut = true;
    }
  }

  // 2. Check if either source or target node is filtered by Table/Logic filters
  if (data.activeTableFilter) {
    if (data.activeTableFilter === HIDE_ALL_VALUE) {
       isFilteredOut = true;
    } else if (data.sourceCategoryId !== data.activeTableFilter || data.targetCategoryId !== data.activeTableFilter) {
       isFilteredOut = true;
    }
  }

  if (data.activeLogicFilter) {
    if (data.activeLogicFilter === HIDE_ALL_VALUE) {
      isFilteredOut = true;
    } else if (data.sourceCategoryId !== data.activeLogicFilter || data.targetCategoryId !== data.activeLogicFilter) {
      isFilteredOut = true;
    }
  }

  // 3. Check Tag Filter
  if (data.activeTagFilter) {
    if (data.activeTagFilter === HIDE_ALL_VALUE) {
      isFilteredOut = true;
    } else {
      // Show edge only if BOTH source and target have the selected tag
      const sourceHasTag = data.sourceTags?.includes(data.activeTagFilter);
      const targetHasTag = data.targetTags?.includes(data.activeTagFilter);
      if (!sourceHasTag || !targetHasTag) {
        isFilteredOut = true;
      }
    }
  }

  const edgeOpacity = isFilteredOut ? 0.05 : 1;

  return (
    <>
      <BaseEdge path={edgePath} markerEnd={markerEnd} style={{
        ...style,
        strokeWidth: selected ? finalWidth + 1 : finalWidth,
        stroke: selected ? '#3b82f6' : finalStroke,
        strokeDasharray: dashArray,
        opacity: edgeOpacity,
        transition: 'all 0.3s'
      }} />
      <EdgeLabelRenderer>
        <div style={{ 
          position: 'absolute', 
          transform: `translate(-50%, -50%) translate(${labelX}px,${labelY}px)`, 
          pointerEvents: 'all',
          opacity: edgeOpacity,
          transition: 'opacity 0.3s'
        }} className="nodrag nopan">
          <div className="flex flex-col items-center gap-1">
            {label && (
