      const timer = setTimeout(() => {
        fitView({ padding: CANVAS_PADDING });
        hasPerformedInitialFit.current = true;
      }, 200);
      return () => clearTimeout(timer);
    }
  }, [nodes.length, fitView]);

  useEffect(() => {
    const projectData = { 
      nodes, 
      edges, 
      settings,
      activeTableFilters,
      activeLogicFilters,
      activeEdgeFilters,
      activeTagFilters
    };
    localStorage.setItem(PROJECT_STORAGE_KEY, JSON.stringify(projectData));
